  "step1a_criteria": {
    "generic_criteria": [
      "Resolves the technical contradiction",
      "Technical feasibility",
      "Cost and scalability"
    ],
    "problem_specific_criteria": [
      "Substantial reduction in black carbon, PM, and CO2",
      "Maintains or increases brick production volume",
      "Low capital investment suitable for small operators",
      "Applicable/retro-fittable to traditional fixed-chimney kilns"
    ]
  },
  "step3a_triz_candidates": {
    "candidates": [
      {
        "principle_number": 22,
        "principle_name": "Blessing in disguise",
        "idea": "Retrofit existing kilns with a low-cost, passive soot/particulate collection system (e.g., baffle chambers or simple cyclone separators built into the flue path). The collected black carbon (the 'bad') is then automatically or manually fed back into the firing zone to be fully combusted, serving as supplementary fuel and increasing energy efficiency ('good').",
        "trace_id": "triz-22"
      },
      {
        "principle_number": 35,
        "principle_name": "Parameter changes",
        "idea": "Implement a low-cost, forced-air injection system (secondary air) downstream of the primary firing ports. This changes the critical combustion parameter (air-to-fuel ratio timing) by introducing high-velocity air jets to ensure complete mixing and burn-off of volatile hydrocarbons and soot particles before they enter the chimney.",
        "trace_id": "triz-35"
      },
      {
        "principle_number": 13,
        "principle_name": "The other way round",
        "idea": "Reverse the draft mechanism: Instead of relying on natural convection (which is inefficient), install a controlled, variable-speed induced draft fan (ID fan) at the top of the chimney. This changes the flow dynamic from uncontrolled suction to managed exhaust, enabling operators to precisely control the air intake and optimize the combustion stoichiometric ratio, mimicking the controlled flow path of a cleaner kiln design.",
        "trace_id": "triz-13"
      },
      {
        "principle_number": 24,
        "principle_name": "Intermediary",
        "idea": "Utilize a reusable, modular flue gas treatment unit (the Intermediary) placed between the kiln exhaust and the fixed chimney. This unit uses low-cost, readily available filtration media (such as hydrated lime, porous low-grade charcoal, or specific clay minerals) to chemically react with SOx/NOx and physically trap particulate matter and black carbon before the gas exits the stack.",
        "trace_id": "triz-24"
      }
    ]
  },
  "step3b_scamper_candidates": {
    "candidates": [
      {
